SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='bf01dab5-2588-5135-846f-b546bb6d98a3'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('ea647c73-cf78-5ec8-9a73-bb1e64da76a5','40e3adea-f581-55f5-9ec0-862d6b6aa916')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='bf01dab5-2588-5135-846f-b546bb6d98a3'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='bf01dab5-2588-5135-846f-b546bb6d98a3'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('ea647c73-cf78-5ec8-9a73-bb1e64da76a5','40e3adea-f581-55f5-9ec0-862d6b6aa916')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='bf01dab5-2588-5135-846f-b546bb6d98a3'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
