  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-csp1-36e9cae1-baseline' AND q.fingerprint='e44f2b57a3bf0dafa3923d8085126cec44dc78f5b4470c3f01e5bacedf15b73f'
