  AND q.result_body='{"contract":"SH-004.v1","requestId":"csp1-36e9cae1-baseline","status":"ok","value":{"customerProfileId":"bf01dab5-2588-5135-846f-b546bb6d98a3","userId":"00e9603c-2f57-5978-8df5-fbff48cddc0d","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"ea647c73-cf78-5ec8-9a73-bb1e64da76a5","semanticKey":"customer-controls-csp1-36e9cae1-baseline","fingerprint":"e44f2b57a3bf0dafa3923d8085126cec44dc78f5b4470c3f01e5bacedf15b73f","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='9ed9df7c-f724-5d48-82a2-4b60fe4b5d6b' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='308819bb-4864-5376-bf46-02b07db147da' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"bf01dab5-2588-5135-846f-b546bb6d98a3"},"prior":null,"committed":{"id":"bf01dab5-2588-5135-846f-b546bb6d98a3","userId":"00e9603c-2f57-5978-8df5-fbff48cddc0d","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='bf01dab5-2588-5135-846f-b546bb6d98a3' AND c.user_id='00e9603c-2f57-5978-8df5-fbff48cddc0d' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
