   AND o.causation_id=q.id::text AND o.correlation_id='csp1-36e9cae1-baseline' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='d54a30b0-d716-5ce8-9774-466f3a626313' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"bf01dab5-2588-5135-846f-b546bb6d98a3","userId":"00e9603c-2f57-5978-8df5-fbff48cddc0d","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='c04c2e9d-4c48-5c19-ac28-be5fba7d280f' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"00e9603c-2f57-5978-8df5-fbff48cddc0d","track":"customer","customerProfileId":"bf01dab5-2588-5135-846f-b546bb6d98a3","sourceCreationRevision":"0","sourceCreationReceipt":"ea647c73-cf78-5ec8-9a73-bb1e64da76a5","semanticKey":"customer_buyer_profile/bf01dab5-2588-5135-846f-b546bb6d98a3/default-free-enrollment/v1"}'::jsonb)))=2));
